        '</ul>';
    } else if (!reposHtml) {
      reposHtml = '<p>No repositories found.</p>';
    }
  } catch (err) {
    console.error('AgentKit error:', err);
    errorMsg = `<p style="color:red">Could not load repositories: ${err.message}</p>`;
  }

  res.status(200).send(`<!DOCTYPE html>
